import json, sys, collections
root = "/Users/luisdehlwes/Documents/00_Events/EHL Finale/worktrees/luis-competitors/competitors/"
th = json.load(open(root + "themes.json"))
themes = {t["id"] for t in th["themes"]}
l2 = th["vfc_level2_to_theme"]
ftypes = set(th["feedback_types"])
feats = {f"F{i:02d}" for i in range(1, 21)}
req = {
 "feedback": ["record_id","review_ref","kind","market","country","brand","model","generation","model_year","powertrain","source_type","source_name","url","published","feedback_type","theme","vfc_level2","comparison","statement","quote","language","rating","evidence_tier"],
 "equipment": ["record_id","kind","market","brand","model","generation","trim_scope","feature","theme","availability","value","source_type","url","as_of","evidence_tier","notes"],
 "competitor": ["record_id","kind","market","brand","model","generation","powertrains","launched","rationale","next_generation","next_generation_evidence_tier","url"],
}
featmap = {"F01":"hmi_infotainment","F02":"hmi_infotainment","F03":"climate","F04":"hmi_infotainment","F05":"connectivity_app_digital","F06":"connectivity_app_digital","F07":"access_locking","F08":"adas_parking","F09":"adas_parking","F10":"seats_comfort","F11":"seats_comfort","F12":"seats_comfort","F13":"ride_handling","F14":"ride_handling","F15":"range_charging_efficiency","F16":"range_charging_efficiency","F17":"space_practicality","F18":"space_practicality","F19":"audio_acoustics","F20":"interior_design_quality"}
ids = set(); errs = []; cnt = collections.Counter(); refs = collections.defaultdict(set); urls=collections.Counter()
for n, line in enumerate(open(root + "raw/cn_nev.jsonl", encoding="utf-8"), 1):
    if not line.strip(): continue
    r = json.loads(line)
    k = r.get("kind")
    for f in req.get(k, []):
        if f not in r: errs.append(f"{n}: missing {f}")
    if r["record_id"] in ids: errs.append(f"{n}: dup id {r['record_id']}")
    ids.add(r["record_id"])
    cnt[(r["model"], k, r.get("source_type"))] += 1
    urls[r.get("url")] += 1
    if k == "feedback":
        refs[(r["model"], r["source_type"])].add(r["review_ref"])
        if r["theme"] not in themes: errs.append(f"{n}: bad theme {r['theme']}")
        if r["feedback_type"] not in ftypes: errs.append(f"{n}: bad ftype")
        v = r["vfc_level2"]
        if v is not None:
            if v not in l2: errs.append(f"{n}: bad vfc {v}")
            elif l2[v] != r["theme"]: errs.append(f"{n}: vfc/theme mismatch {v}->{l2[v]} vs {r['theme']}")
        if r["comparison"] not in (None, "competitor_advantage", "bmw_advantage", "parity"): errs.append(f"{n}: bad comparison")
        if r["evidence_tier"] not in ("A", "B"): errs.append(f"{n}: tier")
        if r["quote"] and len(r["quote"]) > 15: errs.append(f"{n}: long quote")
        if not r["record_id"].startswith("cn_nev-F"): errs.append(f"{n}: id prefix")
    if k == "equipment":
        if r["feature"][:3] not in feats: errs.append(f"{n}: bad feature {r['feature']}")
        elif featmap[r["feature"][:3]] != r["theme"]: errs.append(f"{n}: feature theme mismatch")
        if r["theme"] not in themes: errs.append(f"{n}: bad theme")
        if r["availability"] not in ("standard","optional","not_available","unknown"): errs.append(f"{n}: avail")
print("\n".join(errs) or "OK")
for k, v in sorted(cnt.items(), key=str): print(k, v)
for m, s in sorted(refs.items()): print(m, "reviews:", len(s))
for u, c in urls.most_common(): print(c, u)
EOF
